css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); }
.loader::before, .loader::after { content: ''; position: absolute; border-radius: 9999px; border: calc(var(--loader-size) * .07) solid transparent; }
.loader::before { inset: 0; border-top-color: var(--loader-color); border-bottom-color: var(--loader-color); animation: twSpin var(--loader-speed) linear infinite; }
.loader::after { inset: 24%; border-left-color: var(--loader-secondary-color); border-right-color: var(--loader-secondary-color); animation: twSpinBack calc(var(--loader-speed) * .8) linear infinite; }
@keyframes twSpin { to { transform: rotate(360deg); } }
@keyframes twSpinBack { to { transform: rotate(-360deg); } }
